import java.util.ArrayDeque;
import java.util.Deque;

class Completed {

    public boolean isValid(String s) {

        Deque<Character> stack = new ArrayDeque<>();

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);

            if (c == '(' || c == '[' || c == '{') {
                stack.push(c);
            } else {
                if (stack.isEmpty()) {
                    return false;
                }

                char open = stack.pop();

                if (c == ')' && open != '(') {
                    return false;
                }
                if (c == ']' && open != '[') {
                    return false;
                }
                if (c == '}' && open != '{') {
                    return false;
                }
            }
        }

        return stack.isEmpty();
    }
}

